#!/usr/bin/env python3
"""Embed dashboard/index.html into firmware/arcsense/dashboard_html.h so the ESP32 can serve it.

Run from the project root after editing the dashboard:
    python3 tools/embed_dashboard.py
"""
import pathlib, sys

root = pathlib.Path(__file__).resolve().parent.parent
src = root / "dashboard" / "index.html"
dst = root / "firmware" / "arcsense" / "dashboard_html.h"

html = src.read_text(encoding="utf-8")
if ')rawliteral"' in html:
    sys.exit("dashboard contains the raw-string terminator; remove it")

dst.write_text(
    "// AUTO-GENERATED by tools/embed_dashboard.py - do not edit by hand.\n"
    "#pragma once\n#include <pgmspace.h>\n"
    'const char DASH_HTML[] PROGMEM = R"rawliteral(' + html + ')rawliteral";\n',
    encoding="utf-8",
)
print(f"wrote {dst} ({len(html)} bytes of HTML)")
